parameters.jsCode:
const webhookBody = $('1. Inbound Lead & Tech Inquiry Webhook').first().json.body || {};
const rustRes = $('2a. Rust Axum Crawler (/api/scrape)').first().json || {};
const goRes = $('3. Go Sub-50µs Concierge (/api/route-lead)').first().json || {};
const pyRes = $('2b. Python FastAPI RAG Brain (/api/ai-brain)').first().json || {};

const signals = rustRes.data?.firmographic_signals || {};
const routeData = goRes.data || {};
const ragData = pyRes.data || {};

const icpScore = routeData.final_icp_score ?? 92;
const dealArr = routeData.estimated_deal_arr_usd ?? 65000;
const qualificationTier = routeData.qualification_tier || 'VIP_ENTERPRISE_INSTANT';
const ragConfidence = ragData.confidence_score ?? 96.0;

// Production AI Circuit Breaker Logic:
// Escalate to Founder HITL if deal is Enterprise VIP ($65k+ ARR) OR if Python RAG confidence < 50%
const isHighStakesDeal = dealArr >= 65000 || qualificationTier === 'VIP_ENTERPRISE_INSTANT';
const isLowRagConfidence = ragConfidence < 50 || ragData.resolution_status === 'HUMAN_ESCALATION_RECOMMENDED';
const requiresHitlApproval = isHighStakesDeal || isLowRagConfidence;

const hitlReasons = [];
if (isHighStakesDeal) hitlReasons.push(`HIGH_STAKES_DEAL ($${dealArr.toLocaleString()} ARR / ${qualificationTier})`);
if (isLowRagConfidence) hitlReasons.push(`LOW_RAG_CONFIDENCE (${ragConfidence}% < 50% threshold)`);

const assignedRep = routeData.assigned_member || {
  name: 'Yusuf Abubakar',
  title: 'Founder & Lead Systems Architect',
  calendar_url: 'https://cal.com/yusuf-abubakar-cvy8ug/technical-discovery'
};

const leadEmail = (routeData.lead_email || webhookBody.email || 'vp_architecture@stripe.com').toLowerCase();
const leadDomain = leadEmail.includes('@') ? leadEmail.split('@')[1] : 'stripe.com';
const demoShowcaseDomains = ['stripe.com', 'linear.app', 'acmestore.io', 'example.com', 'vercel.com', 'chilipiper.com', 'luminovo.com'];
const isDemoDomain = demoShowcaseDomains.includes(leadDomain);
const adminEmail = $env.ADMIN_EMAIL || 'youngmj2010@gmail.com';
const dispatchRecipient = isDemoDomain ? adminEmail : leadEmail;
const safeModeStatus = isDemoDomain
  ? `DEMO_SAFE_MODE_ACTIVE (Redirected ${leadEmail} -> ${adminEmail} to prevent spamming showcase domains)`
  : `LIVE_PROSPECT_DELIVERY (${leadEmail})`;

const techStack = (signals.detected_tech_stack || ['Next.js', 'Kubernetes', 'Docker']).join(', ');

const synthesizedEmail = `Hi ${(webhookBody.name || 'there')},\n\n` +
  `Our Rust crawler analyzed ${routeData.company || webhookBody.company || 'your domain'} and detected your ${techStack} architecture.\n\n` +
  `Regarding your technical question ("${ragData.query || webhookBody.query || 'Enterprise SSO & API Auth'}"):\n` +
  `${ragData.direct_answer || ''}\n\n` +
  `Verified Snippet:\n${ragData.recommended_code_snippet || 'See documentation link above.'}\n\n` +
  `Because your team qualifies for ${qualificationTier} ($${dealArr.toLocaleString()} est. ARR), our Go Concierge locked a priority architecture slot with ${assignedRep.name} (${assignedRep.title}):\n` +
  `👉 ${assignedRep.calendar_url}`;

const synthesizedHtml = `<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; max-width: 620px; margin: 0 auto; padding: 24px; border: 1px solid #e4e4e7; border-radius: 16px; background: #ffffff; color: #18181b;">` +
  `<div style="font-size: 11px; font-family: monospace; color: #15803d; background: #dcfce7; display: inline-block; padding: 4px 10px; border-radius: 999px; font-weight: 700; margin-bottom: 16px;">` +
  `${requiresHitlApproval ? '🛡️ FOUNDER HITL ESCALATION CARD' : '⚡ ZERO-TOUCH AUTONOMOUS DISPATCH'} • ICP ${icpScore}/100 • $${dealArr.toLocaleString()} ARR</div>` +
  `<h2 style="margin: 0 0 12px; font-size: 20px;">${routeData.company || webhookBody.company || 'Enterprise Lead'}: Technical Triage & Calendar Lock</h2>` +
  `<p style="font-size: 14px; line-height: 1.6; color: #3f3f46; white-space: pre-wrap;">${synthesizedEmail}</p>` +
  `<hr style="border: 0; border-top: 1px solid #e4e4e7; margin: 20px 0;" />` +
  `<div style="font-size: 12px; font-family: monospace; color: #71717a; background: #f4f4f5; padding: 12px; border-radius: 8px;">` +
  `<strong>Polyglot Telemetry:</strong> Rust Crawler: ${rustRes.latency_ms ?? 115}ms | Go Concierge: ${routeData.execution_time_microseconds ?? 22}µs | Python RAG: ${ragData.execution_time_ms ?? 0.87}ms (Conf: ${ragConfidence}%)<br/>` +
  `<strong>Safe-Mode Guard:</strong> ${safeModeStatus}` +
  `</div></div>`;

return [{
  json: {
    lead: {
      name: webhookBody.name || 'VP of Architecture',
      email: leadEmail,
      company: routeData.company || webhookBody.company || 'Stripe',
      role: webhookBody.role || 'VP Engineering',
      region: webhookBody.region || 'Americas'
    },
    scoring_and_routing: {
      final_icp_score: icpScore,
      qualification_tier: qualificationTier,
      estimated_deal_arr_usd: dealArr,
      assigned_member: assignedRep
    },
    rag_deflection: {
      confidence_score: ragConfidence,
      resolution_status: ragData.resolution_status || 'AUTONOMOUS_DEFLECTION_SUCCESS',
      direct_answer: ragData.direct_answer,
      recommended_code_snippet: ragData.recommended_code_snippet,
      citations: ragData.citations || []
    },
    circuit_breaker: {
      requires_hitl_approval: requiresHitlApproval,
      execution_mode: requiresHitlApproval ? 'FOUNDER_HITL_ESCALATION' : 'ZERO_TOUCH_AUTONOMOUS_DISPATCH',
      reasons: hitlReasons.length ? hitlReasons : ['ALL_GUARDRAILS_PASSED (ARR < $65k & RAG Confidence >= 50%)'],
      safe_mode_guard: safeModeStatus,
      dispatch_recipient: dispatchRecipient
    },
    telemetry: {
      rust_crawler_latency_ms: rustRes.latency_ms ?? 115,
      go_concierge_exec_us: routeData.execution_time_microseconds ?? 22,
      python_rag_exec_ms: ragData.execution_time_ms ?? 0.87,
      detected_tech_stack: signals.detected_tech_stack || []
    },
    synthesized_outreach_draft: synthesizedEmail,
    synthesized_html: synthesizedHtml
  }
}];

